// ============================================================
// UI — dashboard owner TERTANAM di kernel (GET /dash pada port 4000).
// Identik dengan prototipe src/dash-ui.ts (mini-services/server-core).
// ============================================================
package s2.kernel;

public final class Ui {
    private Ui() {}

    public static final String HTML = "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>MINI-SERVER — Dashboard (port 4000)</title>\n<style>\n  :root { color-scheme: dark; }\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  body {\n    background: #0c0a09; color: #e7e5e4; min-height: 100vh;\n    display: flex; flex-direction: column;\n    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n    font-size: 13px; line-height: 1.45;\n  }\n  header {\n    padding: 14px 16px 0; display: flex; flex-wrap: wrap; gap: 10px; align-items: center;\n    border-bottom: 1px solid #292524; background: #1c1917;\n  }\n  header h1 { font-size: 15px; font-weight: 700; letter-spacing: .5px; color: #fafaf9; }\n  .dot { width: 9px; height: 9px; border-radius: 50%; background: #16a34a; display: inline-block; margin-right: 6px; }\n  .dot.err { background: #dc2626; }\n  .badge { border: 1px solid #44403c; border-radius: 6px; padding: 2px 8px; color: #d6d3d1; font-size: 11px; }\n  nav { display: flex; gap: 4px; padding: 10px 16px 0; background: #1c1917; border-bottom: 1px solid #292524; overflow-x: auto; }\n  nav button {\n    background: none; border: 1px solid transparent; border-bottom: none; color: #a8a29e;\n    padding: 8px 14px; cursor: pointer; font: inherit; border-radius: 8px 8px 0 0; white-space: nowrap;\n  }\n  nav button.on { color: #fbbf24; border-color: #292524; background: #0c0a09; }\n  main { flex: 1; padding: 16px; max-width: 1080px; width: 100%; margin: 0 auto; }\n  .panel { background: #1c1917; border: 1px solid #292524; border-radius: 10px; padding: 14px; margin-bottom: 14px; }\n  .panel h2 { font-size: 12px; color: #fbbf24; letter-spacing: 1px; margin-bottom: 10px; }\n  .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; }\n  .kv { background: #0c0a09; border: 1px solid #292524; border-radius: 8px; padding: 8px 10px; }\n  .kv b { display: block; color: #a8a29e; font-size: 10px; text-transform: uppercase; letter-spacing: .5px; }\n  .kv span { color: #fafaf9; word-break: break-all; }\n  table { width: 100%; border-collapse: collapse; }\n  th { text-align: left; color: #78716c; font-size: 10px; text-transform: uppercase; letter-spacing: .5px; padding: 6px 8px; border-bottom: 1px solid #292524; }\n  td { padding: 6px 8px; border-bottom: 1px solid #1c1917; color: #d6d3d1; word-break: break-all; }\n  tr.click { cursor: pointer; } tr.click:hover td { background: #292524; }\n  input, textarea, select {\n    background: #0c0a09; border: 1px solid #44403c; color: #e7e5e4; border-radius: 6px;\n    padding: 7px 9px; font: inherit; width: 100%;\n  }\n  textarea { min-height: 160px; resize: vertical; }\n  button.act {\n    background: #1c1917; color: #fbbf24; border: 1px solid #44403c; border-radius: 6px;\n    padding: 7px 14px; cursor: pointer; font: inherit;\n  }\n  button.act:hover { background: #292524; }\n  button.act.danger { color: #f87171; }\n  .row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-bottom: 10px; }\n  .row > * { flex: 0 0 auto; }\n  .row input, .row select { width: auto; }\n  pre {\n    background: #0c0a09; border: 1px solid #292524; border-radius: 8px; padding: 10px;\n    overflow: auto; max-height: 320px; white-space: pre-wrap; word-break: break-all; color: #d6d3d1;\n  }\n  .muted { color: #78716c; } .ok { color: #4ade80; } .warn { color: #fbbf24; } .err { color: #f87171; }\n  #toast {\n    position: fixed; left: 50%; bottom: 64px; transform: translateX(-50%);\n    background: #1c1917; border: 1px solid #44403c; color: #fafaf9; padding: 9px 16px;\n    border-radius: 8px; opacity: 0; transition: opacity .25s; pointer-events: none; max-width: 90vw;\n  }\n  #toast.show { opacity: 1; }\n  footer {\n    margin-top: auto; padding: 10px 16px calc(10px + env(safe-area-inset-bottom));\n    background: #1c1917; border-top: 1px solid #292524; color: #78716c; font-size: 11px;\n    display: flex; justify-content: space-between; flex-wrap: wrap; gap: 6px;\n  }\n  .hide { display: none; }\n  @media (max-width: 640px) { main { padding: 10px; } .panel { padding: 10px; } }\n</style>\n</head>\n<body>\n<header>\n  <h1><span class=\"dot\" id=\"hdr-dot\"></span>MINI-SERVER — DASHBOARD</h1>\n  <span class=\"badge\">port 4000</span>\n  <span class=\"badge\" id=\"hdr-runtime\">—</span>\n  <span class=\"badge\" id=\"hdr-root\">—</span>\n</header>\n<nav id=\"tabs\">\n  <button data-t=\"status\" class=\"on\">STATUS</button>\n  <button data-t=\"db\">DATABASE</button>\n  <button data-t=\"config\">CONFIG</button>\n  <button data-t=\"handlers\">HANDLERS</button>\n  <button data-t=\"logs\">LOGS</button>\n</nav>\n<main>\n  <section id=\"v-status\">\n    <div class=\"panel\"><h2>MESIN</h2><div class=\"grid\" id=\"g-engine\"></div></div>\n    <div class=\"panel\"><h2>ZONA</h2><div class=\"grid\" id=\"g-zones\"></div></div>\n    <div class=\"panel\"><h2>HANDLER SET AKTIF</h2><div class=\"grid\" id=\"g-handlers\"></div></div>\n    <div class=\"panel\"><h2>SESI WIRE</h2><div class=\"grid\" id=\"g-sessions\"></div></div>\n    <div class=\"panel\"><h2>DATABASE</h2><div class=\"grid\" id=\"g-db\"></div></div>\n  </section>\n\n  <section id=\"v-db\" class=\"hide\">\n    <div class=\"panel\">\n      <h2>STATE KV (data/state.db)</h2>\n      <div class=\"row\">\n        <input id=\"db-search\" placeholder=\"cari kunci…\" style=\"width:200px\">\n        <button class=\"act\" onclick=\"dbLoad()\">MUAT</button>\n        <button class=\"act\" onclick=\"dbSeed()\">SEED ULANG</button>\n      </div>\n      <table><thead><tr><th>KUNCI</th><th>SIZE</th><th>MTIME</th></tr></thead><tbody id=\"db-rows\"></tbody></table>\n    </div>\n    <div class=\"panel\">\n      <h2>LIHAT / UBAH / HAPUS KUNCI</h2>\n      <div class=\"row\"><input id=\"db-key\" placeholder=\"kunci\" style=\"width:220px\"><button class=\"act\" onclick=\"dbGet()\">LIHAT</button></div>\n      <textarea id=\"db-val\" placeholder='nilai (JSON atau teks)'></textarea>\n      <div class=\"row\" style=\"margin-top:8px\">\n        <button class=\"act\" onclick=\"dbPut()\">SIMPAN (PUT)</button>\n        <button class=\"act danger\" onclick=\"dbDel()\">HAPUS</button>\n        <span class=\"muted\" id=\"db-meta\"></span>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"v-config\" class=\"hide\">\n    <div class=\"panel\">\n      <h2>FILE ZONA (engine.json / config / handlers / static)</h2>\n      <div class=\"row\"><button class=\"act\" onclick=\"cfgList()\">MUAT DAFTAR</button><span class=\"muted\">edit file → mesin hot-swap otomatis</span></div>\n      <table><thead><tr><th>PATH</th><th>SIZE</th><th>MTIME</th></tr></thead><tbody id=\"cfg-rows\"></tbody></table>\n    </div>\n    <div class=\"panel\">\n      <h2>EDITOR FILE</h2>\n      <div class=\"row\"><input id=\"cfg-path\" placeholder=\"path file\" style=\"width:260px\"><button class=\"act\" onclick=\"cfgGet()\">BUKA</button><button class=\"act\" onclick=\"cfgPut()\">SIMPAN</button></div>\n      <textarea id=\"cfg-content\" placeholder=\"isi file…\"></textarea>\n    </div>\n  </section>\n\n  <section id=\"v-handlers\" class=\"hide\">\n    <div class=\"panel\">\n      <h2>HANDLER SET</h2>\n      <div class=\"row\"><button class=\"act\" onclick=\"hLoad()\">MUAT</button><button class=\"act warn\" onclick=\"hReload()\">REBUILD SEKARANG</button><span class=\"muted\" id=\"h-meta\"></span></div>\n      <div id=\"h-out\"></div>\n    </div>\n  </section>\n\n  <section id=\"v-logs\" class=\"hide\">\n    <div class=\"panel\">\n      <h2>LOG MESIN</h2>\n      <div class=\"row\">\n        <select id=\"lg-level\"><option value=\"\">semua level</option><option>info</option><option>warn</option><option>error</option><option>wire</option><option>hot</option></select>\n        <select id=\"lg-cat\"><option value=\"\">semua source</option><option>engine</option><option>http</option><option>socket</option><option>db</option><option>hot</option><option>dash</option></select>\n        <select id=\"lg-limit\"><option>100</option><option selected>300</option><option>1000</option></select>\n        <button class=\"act\" onclick=\"lgLoad()\">MUAT</button>\n        <button class=\"act danger\" onclick=\"lgClear()\">BERSIHKAN</button>\n      </div>\n      <table><thead><tr><th>#</th><th>TS</th><th>LVL</th><th>SRC</th><th>PESAN</th></tr></thead><tbody id=\"lg-rows\"></tbody></table>\n    </div>\n  </section>\n</main>\n<footer>\n  <span>SISTEM 2 — mini-server 127.0.0.1:4000</span>\n  <span id=\"ft-uptime\">—</span>\n</footer>\n<div id=\"toast\"></div>\n<script>\nvar TABS = ['status','db','config','handlers','logs'];\nfunction $(id){ return document.getElementById(id); }\nfunction toast(m){ var t=$('toast'); t.textContent=m; t.className='show'; setTimeout(function(){t.className='';},1800); }\nfunction esc(s){ return String(s==null?'':s).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c];}); }\nfunction dur(ms){ var s=Math.floor(ms/1000); var d=Math.floor(s/86400); var h=Math.floor(s%86400/3600); var m=Math.floor(s%3600/60); return (d?d+'h ':'')+(h?h+'j ':'')+m+'m'; }\nfunction api(path, params){\n  var q = params ? ('?'+Object.keys(params).filter(function(k){return params[k]!==undefined&&params[k]!==''&&params[k]!==null;}).map(function(k){return encodeURIComponent(k)+'='+encodeURIComponent(params[k]);}).join('&')) : '';\n  return fetch('/dash/api/'+path+q, { cache:'no-store' });\n}\nfunction apiSend(method, path, body){\n  return fetch('/dash/api/'+path, { method: method, cache:'no-store', headers:{'Content-Type':'application/json'}, body: body ? JSON.stringify(body) : undefined });\n}\n// FIX TAB: dulu semua tombol diberi onclick yang menutup variabel t terakhir\n// (klik tab apa pun selalu menampilkan LOGS). Sekarang tiap tombol pakai\n// data-t miliknya sendiri.\nvar TAB_BTNS = document.querySelectorAll('#tabs button');\nArray.prototype.forEach.call(TAB_BTNS, function(b){\n  var t = b.getAttribute('data-t');\n  b.onclick = function(){\n    Array.prototype.forEach.call(TAB_BTNS, function(x){ x.className=''; });\n    b.className='on'; TABS.forEach(function(x){ $('v-'+x).className = (x===t?'':'hide'); });\n    if (t==='status') statusLoad(); if (t==='db') dbLoad(); if (t==='config') cfgList(); if (t==='handlers') hLoad(); if (t==='logs') lgLoad();\n  };\n});\nstatusLoad();\nfunction kvCell(b, s){ return '<div class=\"kv\"><b>'+esc(b)+'</b><span>'+esc(s)+'</span></div>'; }\nfunction statusLoad(){\n  api('status').then(function(r){ return r.json(); }).then(function(d){\n    if (!d.ok) return;\n    $('hdr-dot').className = 'dot';\n    $('hdr-runtime').textContent = d.engine.runtime;\n    $('hdr-root').textContent = d.zones.root;\n    $('g-engine').innerHTML = kvCell('versi', d.engine.version) + kvCell('port', d.engine.port) + kvCell('uptime', dur(d.engine.uptimeMs)) + kvCell('tea verify', d.tea ? 'LOLOS' : 'GAGAL');\n    $('g-zones').innerHTML = kvCell('root', d.zones.root) + kvCell('config', d.zones.config+' file') + kvCell('handlers', d.zones.handlers+' file') + kvCell('static', d.zones.static+' file') + kvCell('data', d.zones.data+' file');\n    var hb = d.handlers.lastBuildOk ? 'OK' : 'GAGAL';\n    $('g-handlers').innerHTML = kvCell('tier-1 route', d.handlers.tier1Routes) + kvCell('tier-2 handler', d.handlers.tier2Handlers) + kvCell('lib', d.handlers.libModules) + kvCell('hot-swap', d.handlers.reloads+'x') + kvCell('build terakhir', hb) + (d.handlers.lastError ? kvCell('error terakhir', d.handlers.lastError) : '');\n    $('g-sessions').innerHTML = kvCell('sesi engine.io', d.sessions.engineio) + kvCell('websocket aktif', d.sessions.websocket) + kvCell('verified', d.sessions.verified) + kvCell('held', d.sessions.held) + kvCell('held total', d.sessions.heldTotal);\n    $('g-db').innerHTML = kvCell('kunci kv', d.db.keys) + kvCell('file', d.db.file) + kvCell('size', d.db.sizeBytes+' B') + kvCell('log buffer', d.logs.buffer) + kvCell('log drop', d.logs.dropped);\n    $('ft-uptime').textContent = 'uptime '+dur(d.engine.uptimeMs);\n  }).catch(function(){ $('hdr-dot').className='dot err'; });\n}\nsetInterval(statusLoad, 5000); statusLoad();\nfunction dbLoad(){\n  api('db', { search: $('db-search').value, limit: 50 }).then(function(r){ return r.json(); }).then(function(d){\n    if (!d.ok) return toast('gagal muat db');\n    $('db-rows').innerHTML = d.keys.map(function(x){\n      return '<tr class=\"click\" data-k=\"'+esc(x.k)+'\"><td>'+esc(x.k)+'</td><td>'+x.size+' B</td><td class=\"muted\">'+esc(x.mtime)+'</td></tr>';\n    }).join('') || '<tr><td colspan=\"3\" class=\"muted\">(kosong)</td></tr>';\n  });\n}\n$('db-rows').addEventListener('click', function(e){\n  var tr = e.target.closest('tr.click'); if (tr && tr.dataset.k) { $('db-key').value = tr.dataset.k; dbGet(); }\n});\nfunction dbGetByKey(k){ $('db-key').value = k; dbGet(); }\nfunction dbGet(){\n  var k = $('db-key').value; if (!k) return toast('isi kunci dulu');\n  api('db/key', { key: k }).then(function(r){ return r.json(); }).then(function(d){\n    if (!d.ok) { $('db-meta').textContent = d.error; return; }\n    $('db-val').value = d.isJson ? JSON.stringify(d.json, null, 2) : d.raw;\n    $('db-meta').textContent = 'mtime '+d.mtime;\n  });\n}\nfunction dbPut(){\n  var k = $('db-key').value; if (!k) return toast('isi kunci dulu');\n  var v = $('db-val').value, parsed = v;\n  try { parsed = JSON.parse(v); } catch(e) {}\n  apiSend('PUT', 'db/key', { k: k, v: parsed }).then(function(r){ return r.json(); }).then(function(d){ toast(d.ok ? 'kunci tersimpan' : ('gagal: '+d.error)); dbLoad(); });\n}\nfunction dbDel(){\n  var k = $('db-key').value; if (!k) return toast('isi kunci dulu');\n  apiSend('DELETE', 'db/key?key='+encodeURIComponent(k)).then(function(r){ return r.json(); }).then(function(d){ toast(d.ok ? ('dihapus: '+d.deleted) : 'gagal'); dbLoad(); });\n}\nfunction dbSeed(){ apiSend('POST','db/seed').then(function(r){ return r.json(); }).then(function(d){ toast('seed: '+d.imported+' kunci'); dbLoad(); }); }\nfunction cfgList(){\n  api('config').then(function(r){ return r.json(); }).then(function(d){\n    if (!d.ok) return;\n    $('cfg-rows').innerHTML = d.files.map(function(f){\n      return '<tr class=\"click\" data-p=\"'+esc(f.path)+'\"><td>'+esc(f.path)+'</td><td>'+f.size+' B</td><td class=\"muted\">'+esc(f.mtime)+'</td></tr>';\n    }).join('');\n  });\n}\n$('cfg-rows').addEventListener('click', function(e){\n  var tr = e.target.closest('tr.click'); if (tr && tr.dataset.p) { $('cfg-path').value = tr.dataset.p; cfgGet(); }\n});\nfunction cfgGetByKey(p){ $('cfg-path').value = p; cfgGet(); }\nfunction cfgGet(){\n  var p = $('cfg-path').value; if (!p) return toast('isi path dulu');\n  api('config/file', { path: p }).then(function(r){ return r.json(); }).then(function(d){\n    if (!d.ok) return toast(d.error);\n    $('cfg-content').value = d.content; $('db-meta').textContent = '';\n    toast('terbuka: '+p);\n  });\n}\nfunction cfgPut(){\n  var p = $('cfg-path').value; if (!p) return toast('isi path dulu');\n  apiSend('PUT', 'config/file', { path: p, content: $('cfg-content').value }).then(function(r){ return r.json(); }).then(function(d){\n    toast(d.ok ? ('tersimpan + hot-swap '+(d.buildOk?'OK':'GAGAL')) : ('gagal: '+d.error)); cfgList();\n  });\n}\nfunction hLoad(){\n  api('handlers').then(function(r){ return r.json(); }).then(function(d){\n    if (!d.ok) return;\n    var html = '<p class=\"muted\" style=\"margin-bottom:8px\">build terakhir: '+esc(d.lastBuild)+' — '+(d.buildOk?'<span class=\"ok\">OK</span>':'<span class=\"err\">GAGAL</span>')+'</p>';\n    html += '<h2 style=\"font-size:11px;color:#a8a29e;margin:8px 0\">TIER-1 (JSON)</h2><table><thead><tr><th>FILE</th><th>KIND</th><th>ROUTE</th><th>SOURCE</th></tr></thead><tbody>'+\n      d.tier1.map(function(r){ return '<tr><td>'+esc(r.file)+'</td><td>'+esc(r.kind)+'</td><td>'+esc(r.route)+'</td><td class=\"muted\">'+esc(r.source)+'</td></tr>'; }).join('')+'</tbody></table>';\n    html += '<h2 style=\"font-size:11px;color:#a8a29e;margin:12px 0 8px\">TIER-2 (JS)</h2><table><thead><tr><th>FILE</th><th>ID</th><th>KIND</th><th>ROUTE</th></tr></thead><tbody>'+\n      d.tier2.map(function(r){ return '<tr><td>'+esc(r.file)+'</td><td>'+esc(r.id)+'</td><td>'+esc(r.kind)+'</td><td>'+esc(r.route)+'</td></tr>'; }).join('')+'</tbody></table>';\n    html += '<h2 style=\"font-size:11px;color:#a8a29e;margin:12px 0 8px\">LIB</h2><table><tbody>'+\n      d.lib.map(function(r){ return '<tr><td>'+esc(r.file)+'</td></tr>'; }).join('')+'</tbody></table>';\n    $('h-out').innerHTML = html;\n  });\n}\nfunction hReload(){\n  apiSend('POST','reload').then(function(r){ return r.json(); }).then(function(d){\n    toast('reload: tier1='+d.tier1Routes+', tier2='+d.tier2Handlers+(d.error?(' — '+d.error):''));\n    hLoad();\n  });\n}\nfunction lgLoad(){\n  api('logs', { level: $('lg-level').value, category: $('lg-cat').value, limit: $('lg-limit').value }).then(function(r){ return r.json(); }).then(function(d){\n    if (!d.ok) return;\n    $('lg-rows').innerHTML = d.logs.map(function(e){\n      var cls = e.level==='error'?'err':(e.level==='warn'?'warn':(e.level==='wire'?'ok':''));\n      return '<tr><td class=\"muted\">'+e.seq+'</td><td class=\"muted\">'+esc(e.ts)+'</td><td class=\"'+cls+'\">'+esc(e.level)+'</td><td>'+esc(e.category)+'</td><td>'+esc(e.msg)+'</td></tr>';\n    }).join('') || '<tr><td colspan=\"5\" class=\"muted\">(kosong)</td></tr>';\n  });\n}\nfunction lgClear(){ apiSend('POST','logs/clear').then(function(r){ return r.json(); }).then(function(d){ toast(d.ok?'log dibersihkan':'gagal'); lgLoad(); }); }\n$('lg-level').onchange = lgLoad; $('lg-cat').onchange = lgLoad;\n</script>\n</body>\n</html>";
}